import React, { useEffect, useState } from 'react';
import { Outlet, useLocation } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { useResponsive } from '../../../hooks/useResponsive';
import { fetchUnreadCount } from '../../../store/slices/notificationSlice';
import { fetchUnreadMessageCount } from '../../../store/slices/messagesInboxSlice';
import { Topbar } from '../Topbar';
import { ErrorBoundary } from '../ErrorBoundary';
import { NotificationCenter, MessageCenter } from '@linm-soft/common-components';
import { AppSwitcher, AppDef, AppId, APPS } from '@linm-soft/common-components';
import { signalRService } from '../../../services/signalr';
import { UserRole } from '../../../models/User';
import { SwitchCompanyModal } from '../SwitchCompanyModal';
import styles from './AppLayout.module.css';

const getActiveApp = (pathname: string): AppId => {
  if (pathname.startsWith('/medical-incidents')) return 'medical-incidents';
  if (pathname.startsWith('/fall-location-warnings')) return 'medical-incidents';
  return 'task-management';
};

export const AppLayout: React.FC = () => {
  const location = useLocation();
  const dispatch = useAppDispatch();
  const currentUser = useAppSelector((state) => state.auth.user);

  const { isMobile } = useResponsive();
  const [isSwitchCompanyOpen, setIsSwitchCompanyOpen] = useState(false);

  useEffect(() => {
    if (currentUser?.id) {
      dispatch(fetchUnreadCount());
      dispatch(fetchUnreadMessageCount());
    }
  }, [currentUser?.id, dispatch]);

  useEffect(() => {
    if (!currentUser?.id) return;
    return signalRService.onReconnected(() => {
      dispatch(fetchUnreadCount());
      dispatch(fetchUnreadMessageCount());
    });
  }, [currentUser?.id, dispatch]);

  useEffect(() => {
    const handler = () => {
      if (document.visibilityState === 'visible' && currentUser?.id) {
        dispatch(fetchUnreadCount());
      }
    };
    document.addEventListener('visibilitychange', handler);
    return () => document.removeEventListener('visibilitychange', handler);
  }, [currentUser?.id, dispatch]);

  const activeApp = getActiveApp(location.pathname);
  const activeAppDef = APPS.find((a) => a.id === activeApp) ?? APPS[0];

  const handleAppSwitch = (app: AppDef) => navigateToUrl(app.homeRoute);
  const handleShellNavigate = (path: string) => navigateToUrl(path);

  const getPageTitle = () => {
    const path = location.pathname;
    if (path === '/admin/companies') return 'Quản lý Công ty';
    if (path === '/admin/users') return 'Quản lý Người dùng';
    if (path === '/admin/departments') return 'Quản lý Phòng ban';
    if (path === '/admin/accounts') return 'Quản lý Tài khoản';
    if (path === '/admin/permissions') return 'Phân quyền';
    if (path === '/admin/data-cleanup') return 'Dọn dẹp Go-Live';
    return activeAppDef.name;
  };

  return (
    <div className={styles.main} data-modal-root>
      <Topbar
        title={getPageTitle()}
        onSearch={(query) => console.log('Search:', query)}
        showMenuButton={isMobile}
        onMenuClick={() => window.dispatchEvent(new CustomEvent('linm:nav:toggle-mobile'))}
        notificationSlot={<NotificationCenter onNavigate={handleShellNavigate} />}
        rightSlot={
          <>
            {currentUser?.role === UserRole.Admin && (
              <button
                className={styles.switchCompanyBtn}
                onClick={() => setIsSwitchCompanyOpen(true)}
                title="Chuyển đổi công ty"
                aria-label="Chuyển đổi công ty"
              >
                <i className="fas fa-exchange-alt" />
                {!isMobile && <span className={styles.switchCompanyLabel}>Đổi công ty</span>}
              </button>
            )}
            <MessageCenter onNavigate={handleShellNavigate} />
          </>
        }
        leftSlot={<AppSwitcher activeApp={activeApp} onSwitch={handleAppSwitch} userRole={currentUser?.role} />}
      />
      {currentUser?.role === UserRole.Admin && (
        <SwitchCompanyModal
          isOpen={isSwitchCompanyOpen}
          onClose={() => setIsSwitchCompanyOpen(false)}
        />
      )}
      <div className={styles.content}>
        <ErrorBoundary>
          <Outlet />
        </ErrorBoundary>
      </div>
    </div>
  );
};

export default AppLayout;
